package dashboard.enterprise.agent.llm.prompt;import dashboard.enterprise.agent.llm.model.PromptTemplate;import dashboard.enterprise.agent.skillstudio.model.SkillPackage;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.Map;public final class PromptLoader{public PromptTemplate load(SkillPackage skill,String entrypoint)throws Exception{Path p=skill.packageRoot().resolve(entrypoint).normalize();if(!p.startsWith(skill.packageRoot())||!Files.isRegularFile(p))throw new IllegalArgumentException("Prompt entrypoint is missing or outside skill package: "+entrypoint);return new PromptTemplate("mapaf.llm.prompt/v1",skill.manifest().skillId()+":"+entrypoint,skill.manifest().version(),Files.readString(p,StandardCharsets.UTF_8),"{{input}}",Map.of("skill",skill.coordinate()));}}
